// is the smAgent-side backstop; fixing the step's success criteria is an
// awf-repo follow-up.
var EMPTY_LAP_MARKER_RE = /\uD83C\uDF00 empty rework lap (\d+)\/(\d+) \u2014 head ([0-9a-f]{7,40}) unchanged/g;

function emptyLapMaxOf(jobParams) {
    var n = (jobParams || {}).emptyLapMax;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    // Default 1 (review #703 retune; was 2) — see the reachability note
    // above: at 2 the WITHHELD branch never fired under redHeadCap=3.
    return (typeof n === 'number' && n > 0) ? Math.floor(n) : 1;
}

// gh-957: the no-op loop guard budget — consecutive rework legs on the SAME
// head that closed with ZERO pushed commits AND ZERO resolved threads
// (live dart #424: 7 legs / 2h, every one 'successful', threads never
// resolved, arm re-matched every tick). At the cap the threads-armed and
// red-gated arm_rework paths AND the gh-840 restore sweep withhold the arm
// and escalate the owner once per head (label + 🛑 comment). A lap that
// pushed OR resolved anything, or a new head, resets the count by
// construction (the lap markers are head-keyed).
function noopLapMaxOf(jobParams) {
    var n = (jobParams || {}).noopLapMax;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    return (typeof n === 'number' && n > 0) ? Math.floor(n) : reworkLoopGuardModule.DEFAULT_NOOP_LAP_MAX;
}

// Invalidate-after-mutation (owner directive 2026-10-04): PR labels changed
// mid-tick — a later rule re-querying the open-PR list in the SAME tick
// (validate-armed's mutex) must see it. Guarded: harnesses may stub the
// provider module down to createSmProvider alone.
function dropOpenPrsCache(repoInfo) {
    try {
        if (smProviderModule && typeof smProviderModule.ioCacheDrop === 'function') {
            smProviderModule.ioCacheDrop(
                repoInfo.owner, repoInfo.repo, 'openPrs', null);
        }
    } catch (eDrop) { /* stale cache costs one extra tick, never a wrong arm */ }
}

// gh-862: the merge-validated probe — the squash-merge attempt shared by
// the merge_pr action, the latch-skip arm-only path and the gh-857
// conclude-success path. Live fa #1457 (rel-20261011-204928, two ticks
// 21:01Z/21:06Z): the latch-skip armed ai_validating WITHOUT a dispatch
// and continued — but merge-validated runs EARLIER in the deployed rule
// order (sm_github.json index 6 vs validate-armed 11), so the arm landed
// after the merge window had already closed; the sweep ate the arm next
// tick ('stale arm swept') and the latch-skip re-armed — arm → sweep →
// re-arm ping-pong, the conclude and the merge unreachable for exactly
// the PRs that need them. Every ai_validated + green PR must get the
// probe (placeholder conclude first, then the merge attempt) in the tick
// that arms/concludes it.
// Returns 'merged' | 'latched' (an un-approved green head: ai_validating
// unarmed + ai_validated latched, review follows — review-after-dev
// requires ai_validated). THROWS on a refused merge (anything but an
// explicit merged:true — fa pr-753 parity: the HTTP layer returns the
// raw body for error statuses, a 405 "not mergeable" arrives as
// {"merged": false, ...} with NO thrown error; the markers MUST stay so
// the loop self-heals: unarm-stale → refresh → re-validate → retry).
function attemptMergeProbe(repoInfo, ticket, key) {
    // Verify the sticky pr_approved latch on the PR itself (defense in
    // depth for the rule guards — the query list may be a stale snapshot).
    var gateRaw = github_get_pr({
        workspace: repoInfo.owner,
        repository: repoInfo.repo,
        pullRequestId: ticket.prNumber
    });
    var gatePr = {};
    try {
        gatePr = typeof gateRaw === 'string' ? JSON.parse(gateRaw) : (gateRaw || {});
    } catch (gateParseErr) { gatePr = {}; }
    var gateLabels = (gatePr.labels || []).map(function (l) {
        return (l && l.name) || l;
    });
    if (gateLabels.indexOf('pr_approved') === -1) {
        githubTracker(repoInfo.owner, repoInfo.repo).removeLabel(ticket.prNumber, 'ai_validating');
        githubTracker(repoInfo.owner, repoInfo.repo).addLabel(ticket.prNumber, 'ai_validated');
        console.log('  ✅ ' + key + ' validated (no approval yet) — ai_validated latched, review follows');
        return 'latched';
    }
    var mergeRaw = github_merge_pr({
        workspace: repoInfo.owner,
        repository: repoInfo.repo,
        pullRequestId: ticket.prNumber,
        mergeMethod: 'squash'
    });
    var mergeResp = {};
    try {
        mergeResp = typeof mergeRaw === 'string' ? JSON.parse(mergeRaw) : (mergeRaw || {});
    } catch (parseErr) { /* non-JSON body counts as refusal */ }
    if (mergeResp.merged !== true) {
        throw new Error('merge refused: ' +
            (typeof mergeRaw === 'string' ? mergeRaw : JSON.stringify(mergeRaw)));
    }
    try {
        githubTracker(repoInfo.owner, repoInfo.repo).removeLabel(ticket.prNumber, 'ai_validating');
        githubTracker(repoInfo.owner, repoInfo.repo).removeLabel(ticket.prNumber, 'pr_approved');
        githubTracker(repoInfo.owner, repoInfo.repo).removeLabel(ticket.prNumber, 'ai_validated');
    } catch (e2) { /* absent labels are fine post-merge */ }
    console.log('  🎉 ' + key + ' squash-merged');
    return 'merged';
}

// Action-time mutex re-verification for the validate_pr arms (owner
// directive 2026-10-04, live fa 12:0x double-arm: #1194 + #1215 both held
// ai_validating after a manual strip + tick). Mirrors githubSource's
// query-time scan — same semantics, LIVE data: the rule's own query.mutex
// label, holders scoped by mutexAmong, 'blocked' holders invisible (a
// frozen arm must not serialize the window), the candidate itself never
// blocks itself, and query.mutexExcludeSelf honored: a SELF-HOLDING
// candidate of a recovery rule (revalidate-armed/-green) is never blocked
// by other holders — it drains the leaked stack (#577 parity).
// Reads github_list_prs DIRECTLY —
// deliberately bypassing the per-tick ioCache, whose staleness is exactly
// the hole this closes. Returns the holder's PR number, or 0/false when
// the arm may proceed (including on probe error — fail OPEN: the
// query-level mutex still guards the common case, a probe outage must not
