        var runs = mcpParse((res || {}).output ||
                            (res || {}).stdout || res);
        var list = (runs && runs.workflow_runs) || [];
        var now = Date.now();
        return list.some(function (r) {
            if (validationLivenessModule.ACTIVE_RUN_STATES.indexOf(r.status) !== -1) return true;
