'use strict';

var MAX_ALARMS = 20;

// ── I1 — derive(M): reconciliation from the label layer ─────────────────────

function normalizeHolder(h) {
    if (h && typeof h === 'object') {
        var n = h.pr || h.prNumber || h.number || 0;
        return Math.floor(Number(n)) || 0;
    }
    var m = Math.floor(Number(h));
    return isNaN(m) ? 0 : m;
