                // this extends it to rework/review legs. The exclusion is
                // probed FRESH every tick (a leg that finished between ticks
                // does not block — AC2), and the refresh is not lost — the
                // PR is still BEHIND and refreshes on the first tick after
                // the leg finishes.
                var legWorkflowUb = rule.workflowFile || 'ai-teammate.yml';
                // gh-846: the refresh just moved the head — every dispatched
                // validation run on a superseded head is dead weight on the
                // (scarce, mac) runner queue. Cancel in the SAME tick as the
                // refresh (AC1), after the push, against the FRESH head —
                // the ticket-cached sha is the pre-refresh one. One
                // bookkeeping comment records the cancelled-as-stale heads
                // (gh-755 parity: CANCELLED is never a verdict — nothing on
                // the old head trips fail-validation / zombie re-dispatch /
                // red-head counting; those all key on the current head).
                var cancelStaleAfterRefreshUb = function () {
                    var newHeadUb = freshHeadSha(effectiveRepoInfo, ticket.prNumber);
                    if (!newHeadUb) return; // fail closed — retried next refresh
                    var ubCancelResult = cancelStaleDispatchedRuns(
                        effectiveRepoInfo,
                        rule.ciWorkflow ||
                            ((RUN_JOB_PARAMS || {}).ciWorkflow) || 'quality.yml',
                        ticket.branch, newHeadUb);
                    // gh-848 audit: deferred cancels / belt-cleaned ghosts
                    // get their own one-marker-per-head bookkeeping.
                    postGhostGuardAudit(effectiveRepoInfo, ticket.prNumber,
                                        ubCancelResult);
                    var staleCancelledUb = ubCancelResult.cancelled;
                    if (!staleCancelledUb.length) return;
                    if (!DRY) {
                        try {
                            var seenUb = {};
                            var linesUb = [];
                            staleCancelledUb.forEach(function (r) {
                                var sha = String((r && r.head_sha) || '');
                                if (sha && !seenUb[sha]) {
                                    seenUb[sha] = true;
                                    linesUb.push(validationLivenessModule
                                        .staleCancelMarkerLine(sha, new Date().toISOString()));
                                }
                            });
                            githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).postComment(ticket.prNumber, linesUb.join('\n') + '\n\n' + 'Cancelled ' + staleCancelledUb.length + ' validation run(s) ' + 'dispatched on a superseded head of this PR — the silent refresh ' + 'moved the base and their results would be discarded anyway ' + '(gh-846). `cancelled` is not a verdict (gh-755): no ' + 'fail-validation, no zombie re-dispatch, no red-head count is ' + 'recorded for these heads — validation re-dispatches only on the ' + 'current head.');
                        } catch (eStaleMark) {
                            console.warn('  ⚠️  stale-cancel marker comment failed: ' +
                                         (eStaleMark.message || eStaleMark));
                        }
                    }
                };
                if (uHead) {
                    var headRunsUb = headWorkflowRunsSafe(effectiveRepoInfo, uHead);
                    if (headRunsUb !== null &&
                        hasActiveLegRun(headRunsUb, legWorkflowUb)) {
                        console.log('  ⏭️  ' + key + ' branch refresh deferred — an ai-teammate leg is in flight on the head' +
                            ' (refreshes on the first tick after it finishes)');
                    } else if (headRunsUb === null) {
                        // Probe failure FAILS CLOSED: one deferred refresh
                        // costs a tick; racing a live leg costs the leg's
                        // whole push stream.
                        console.warn('  ⚠️  ' + key +
                            ' head-run probe failed — branch refresh deferred (fail closed, gh-798)');
                    } else {
                        silentUpdateBranch(ticket.branch);
                        console.log('  ✅ ' + key + ' branch silently updated (no CI)');
                        cancelStaleAfterRefreshUb();
                    }
                } else {
                    // No resolvable head sha: no probe possible — the
                    // pre-gh-798 behavior stands (refresh rides the branch
                    // name alone). Residual race, DELIBERATE fail-open
                    // (gh-798 review): a leg landing on an unprobed head is
                    // NOT prevented here — the timer's
                    // pushBranchWithSelfHeal heals that push harness-side
                    // (fetch+merge+retry). Deferring on an
                    // unresolvable-but-existing head would close the hole
                    // for one tick of delay; the heal backstop was chosen
                    // instead so a flaky API never freezes freshness.
                    silentUpdateBranch(ticket.branch);
                    console.log('  ✅ ' + key + ' branch silently updated (no CI)');
                    cancelStaleAfterRefreshUb();
                }

