var HEAD = '23dacd10deadbeefcafe0123456789abcdef0123';
var OTHER = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
var HOUR_MS = 60 * 60 * 1000;

