        out.state.phantomHolderTicks++;
        out.state.alarms.push(out.alarm);
        if (out.state.alarms.length > MAX_ALARMS) {
            out.state.alarms = out.state.alarms.slice(-MAX_ALARMS);
        }
    } else {
        out.state.consecutivePhantomTicks = 0;
    }
    return out;
}

