// ── I2 — reconcile: self-heal with alarm, tick counters ─────────────────────

function iso(nowMs) {
    try { return new Date(nowMs).toISOString(); }
    catch (e) { return String(nowMs); }
}

function initialState(nowMs) {
    return {
        registry: [],
        mutexSelfHeals: 0,
        phantomHolderTicks: 0,
        consecutivePhantomTicks: 0,
        alarms: [],
        sinceMs: nowMs || null
    };
}

