// writer rule); this module reconciles the label layer only.

var MAX_ALARMS = 5;
var PHANTOM_ALARM_CAP = 3;
var FRESH_CANCEL_GRACE_MS = 15 * 60 * 1000; // gh-755 — do not re-dispatch a cancel still within its visibility grace

