    switch (String(conclusion || '').toLowerCase()) {
        case 'success': return { verdict: 'success', reDispatch: false };
        case 'failure': return { verdict: 'failure', reDispatch: false };
        case 'cancelled':
        case 'canceled':
        case 'timed_out': return { verdict: null, reDispatch: true };
