            // confirm; it is a phantom source, not a holder
            if (candSet[n]) phantoms.push(n);
            return false;
        }
        return true;
    });
    return {
        holders: liveHolders,
        phantoms: phantoms,
        armedExtra: armedExtra,
        repo: repo || null,
        at: nowIso || null
