    (p.alarms || []).concat(e.alarm ? [e.alarm] : []).forEach(function (a) {
        if (!a) return;
        var key = str(a.type) + '|' + String(a.holders && a.holders.cached) + '|' + str(a.at);
        if (seen[key]) return;
        seen[key] = true;
        out.alarms.push(a);
    });
    while (out.alarms.length > MAX_ALARMS) out.alarms.shift();
    return out;
}

