}

// ── I2 — reconcile: self-heal with alarm, tick counters ─────────────────────

function defaultState() {
    return { mutexSelfHeals: 0, phantomHolderTicks: 0, consecutivePhantomTicks: 0, alarms: [] };
}

/**
