        label: 'ai_validating',
        repo: (liveSnapshot && liveSnapshot.repo) || (cachedSnapshot && cachedSnapshot.repo) || null,
        holders: { cached: cached, live: live },
        at: (liveSnapshot && liveSnapshot.at) || null
